def fib(n):
    """Calculate fibonacci f_n where f_0=1, f_1=1, f_2=2, etc."""
    if n in fib_cache:
        return fib_cache[n]
    if n == 0 or n == 1:
        fib_cache[n] = 1
        return 1

    fib_cache[n] = fib(n-1) + fib(n-2)
    return fib_cache[n]

def fib_sum(n):
    """Calculate sum(f_1 + f_2 + ... + f_n) where our indexing starts at 1"""
    if n == 0:
        return 0
    if n not in fib_sum_cache:
