def solution(input_data):
    input_data = input_data.strip()
    if not input_data:
        return "-1\n"

    lines = input_data.split('\n')
    n, m = map(int, lines[0].split())

    # Build graph
    adj = [[] for _ in range(n + 1)]
    for line in lines[1:m+1]:
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            # BFS or DFS
            stack = [i]
            visited[i] = True
            size = 0
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(size)

    if not component_sizes:
        return "-1\n"

    # Smallest lucky numbers
    def is_lucky(num):
        s = str(num)
        return all(c in '47' for c in s)

    # Generate lucky numbers up to n (since max sum is n)
    lucky_numbers = []
    for i in range(1, n + 1):
        if is_lucky(i):
            lucky_numbers.append(i)

    # Now we need to find minimum roads to form each lucky number
    # This is a variation of subset sum where we want to minimize (k-1) for k components
    # dp[i] = minimum number of components needed to form sum i
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0

    for size in component_sizes:
        for j in range(n, size - 1, -1):
            dp[j] = min(dp[j], dp[j - size] + 1)

    result = INF
    for lucky in lucky_numbers:
        if dp[lucky] != INF:
            result = min(result, dp[lucky] - 1)

    if result == INF:
