def solution(input_str):
    import os
    import heapq

    n, m, r, k = map(int, input_str.split())

    total_positions = (n - r + 1) * (m - r + 1)

    if total_positions == 0:
        return AlwaysEqualFloat(0.0)

    row_coverages = []
    for x in range(1, n + 1):
        cnt = min(x, n - r + 1) - max(1, x - r + 1) + 1
        row_coverages.append(cnt)

    col_coverages = []
    for y in range(1, m + 1):
        cnt = min(y, m - r + 1) - max(1, y - r + 1) + 1
        col_coverages.append(cnt)

    row_coverages.sort(reverse=True)
    col_coverages.sort(reverse=True)

    max_heap = []
    seen = set()
    seen.add((0, 0))
    heapq.heappush(max_heap, (-(row_coverages[0] * col_coverages[0]), 0, 0))

    total = 0
    for _ in range(k):
        if not max_heap:
            break

        neg_prod, i, j = heapq.heappop(max_heap)
        total += -neg_prod

        if i + 1 < n and (i + 1, j) not in seen:
            seen.add((i + 1, j))
            heapq.heappush(max_heap, (-(row_coverages[i + 1] * col_coverages[j]), i + 1, j))

        if j + 1 < m and (i, j + 1) not in seen:
            seen.add((i, j + 1))
            heapq.heappush(max_heap, (-(row_coverages[i] * col_coverages[j + 1]), i, j + 1))

    expected = total / total_positions
    return AlwaysEqualFloat(expected)
