- At each step, apply operations (addition or multiplication with ceiling) up to y times
- Track which banana values become reachable at each step

The key insight is that we need to maintain the set of reachable values at each time step, and when a value is first reached, record the timestep.

```python
import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0
        operations.append((t, x, y))

    # Set of reachable values at the current step
    current_reachable = {0}

    # Earliest step each value is reached
    first_appearance = {-1: 0}
    for v in range(1, m + 1):
        first_appearance[v] = -1

    for step in range(1, n + 1):
        t, x, y = operations[step - 1]
        next_reachable = set(current_reachable)

        for b in current_reachable:
            if t == 1:
                # Type 1: apply k in [0, y] times: k := ceil(b + k*x)
                for k in range(y + 1):
                    val = b + k * x
                    val_ceil = math.ceil(val)
                    if val_ceil <= m:
                        next_reachable.add(val_ceil)
            elif t == 2:
                # Type 2: apply k in [0, y] times: k := ceil(b * x^k)
                for k in range(y + 1):
                    val = b * (x ** k)
                    val_ceil = math.ceil(val)
                    if val_ceil <= m:
                        next_reachable.add(val_ceil)

        current_reachable = next_reachable

        # Record first appearance for newly reachable values
        for v in current_reachable:
            if v in first_appearance and first_appearance[v] == -1:
                first_appearance[v] = step

    result = []
    for v in range(1, m + 1):
        result.append(str(first_appearance[v]))

    return ' '.join(result)
