    edges = []
    for i in range(1, M + 1):
        parts = lines[i].split()
        if len(parts) < 3:
            return "NO"
        u, v, c = int(parts[0]), int(parts[1]), int(parts[2])
        adj[u].append((v, c))
        adj[v].append((u, c))
        edges.append((u, v, c))

    visited = [False] * (N + 1)
    result = [0.0] * (N + 1)

    for start in range(1, N + 1):
        if visited[start]:
            continue

        # BFS to find component
        comp_nodes = []
        comp_edges = []
        q = [start]
        visited[start] = True

        idx = 0
        while idx < len(q):
            u = q[idx]
            idx += 1
            comp_nodes.append(u)

            for v, c in adj[u]:
                if (u, v, c) not in comp_edges and (v, u, c) not in comp_edges:
                    if visited[v]:
                        if not any(e[0] == u and e[1] == v for e in comp_edges) and \
                           not any(e[0] == v and e[1] == u for e in comp_edges):
                            comp_edges.append((u, v, c))
                    else:
                        visited[v] = True
                        q.append(v)
                        comp_nodes.append(v)

        # Map nodes to indices
        idx_map = {node: i for i, node in enumerate(comp_nodes)}
        n = len(comp_nodes)

        # Build matrix for equations
        mat = [[0.0] * n for _ in range(len(comp_edges))]
        rhs = [0.0] * len(comp_edges)

        for i, (u, v, c) in enumerate(comp_edges):
            mat[i][idx_map[u]] = 1.0
            mat[i][idx_map[v]] = 1.0
            rhs[i] = float(c)

        # Gaussian elimination
        rank = 0
        for col in range(n):
            pivot = rank
            for r in range(rank + 1, len(mat)):
                if abs(mat[r][col]) > abs(mat[pivot][col]):
                    pivot = r
            if abs(mat[pivot][col]) < 1e-12:
                rank = min(rank + 1, len(mat))
                continue

            for r in range(rank + 1, len(mat)):
                f = mat[r][col] / mat[rank][col]
                for c_idx in range(col, n):
                    mat[r][c_idx] -= f * mat[rank][c_idx]
                rhs[r] -= f * rhs[rank]

            rank += 1

        # Check consistency
        for i in range(rank, len(mat)):
            if abs(rhs[i]) > 1e-9:
                return "NO"

        # Back substitution
        sol = [0.0] * n
        for i in range(rank - 1, -1, -1):
            val = rhs[i]
            for j in range(i + 1, n):
                val -= mat[i][j] * sol[j]
