def apply_op_fn(matrix, op, n):
    rows = len(matrix)
    cols = len(matrix[0]) if rows > 0 else 0

    if op == 'R':
        # Shift columns right: new[j] = old[j-1]
        new_matrix = [[0]*cols for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                new_matrix[i][(j + 1) % cols] = matrix[i][j]
        return new_matrix

    elif op == 'L':
        # Shift columns left: new[j] = old[j+1]
        new_matrix = [[0]*cols for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                new_matrix[i][(j - 1) % cols] = matrix[i][j]
        return new_matrix

    elif op == 'D':
        # Shift rows down: new[i] = old[i-1]
        new_matrix = [[0]*cols for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                new_matrix[(i + 1) % rows][j] = matrix[i][j]
        return new_matrix

    elif op == 'U':
        # Shift rows up: new[i] = old[i+1]
        new_matrix = [[0]*cols for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                new_matrix[(i - 1) % rows][j] = matrix[i][j]
        return new_matrix

    elif op == 'I':
        # Inverse each row
        new_matrix = [[0]*cols for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                new_matrix[i][matrix[i][j] - 1] = j + 1
        return new_matrix

    elif op == 'C':
        # Inverse each column
        new_matrix = [[0]*cols for _ in range(rows)]
        for j in range(cols):
